const text = ($json.text || '').trim();
const up = text.toUpperCase();
const m = up.match(/(?:^|\s)\$?([A-Z]{1,5})(?:\s|$)/);
const ticker = m ? m[1] : null;
const macroTerms = ['MACRO','ECON','ECONOMIC','CALENDAR','DATA'];
const askMacro = macroTerms.some(t => up.includes(t)) && up.includes('TODAY');
let intent = 'fallback';
if (ticker && /(PRICE|UPDATE|QUOTE|WHAT|HOW|UP|DOWN)/.test(up)) intent = 'ticker_update';
else if (askMacro) intent = 'us_macro_today';
return [{ json: { intent, ticker, date: new Date().toISOString().slice(0,10), channel: $json.channel, user: $json.user, original: text } }];

const root = $items('ParseIntent',0,0).json;
const intent = root.intent;
const channel = root.channel;
const ticker = root.ticker;
if (intent === 'ticker_update') {
  const fin = $items('FinnhubQuote',0,0)?.json || {};
  const av  = $items('AlphaVantageQuote (fallback)',0,0)?.json || {};
  let out;
  if (fin.c) {
    out = { source:'finnhub', ticker, price: fin.c, change: fin.d, percent: fin.dp, high: fin.h, low: fin.l, open: fin.o, prevClose: fin.pc };
  } else if (av['Global Quote']) {
    const g = av['Global Quote'];
    out = { source:'alphavantage', ticker: g['01. symbol'] || ticker, price: Number(g['05. price']), change: Number(g['09. change']), percent: Number((g['10. change percent']||'0').replace('%','')), high: Number(g['03. high']), low: Number(g['04. low']), open: Number(g['02. open']), prevClose: Number(g['08. previous close']) };
  } else {
    out = { error: 'No price data' };
  }
  return [{ json: { intent, channel, formatted: out } }];
}
if (intent === 'us_macro_today') {
  const cal = $items('FinnhubEconCalendar',0,0)?.json || {};
  const tz = $env.TIMEZONE || 'Europe/Amsterdam';
  const list = (cal.economicCalendar || cal.result || []);
  const events = list.map(e => ({
    time_local: new Date(e.time || e.datetime).toLocaleTimeString('en-US', { timeZone: tz, hour: '2-digit', minute: '2-digit' }),
    event: e.event || e.title,
    country: e.country || 'US',
    actual: e.actual || e.actual_value || null,
    forecast: e.estimate || e.forecast || null,
    previous: e.previous || null,
    importance: e.importance || e.impact || null
  }));
  return [{ json: { intent, channel, formatted: { date: root.date, events } } }];
}
return [{ json: { intent: 'fallback', channel, formatted: { note: 'Unsupported query' } } }];

const channel = $items('FormatData',0,0).json.channel;
const choices = $json.choices || [];
const text = choices[0]?.message?.content || $json.text || JSON.stringify($json);
return [{ json: { channel, text } }];
